#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
PUBLIC_IP="90.189.208.25"
LAN_IP="192.168.0.179"

SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
SERVER_ROOT="/srv/hyper-cs16/servers/${SID}"
CSTRIKE="$SERVER_ROOT/cstrike"
FASTDL="/srv/hyper-cs16/fastdl/${SID}"
NGINX_CONF="/etc/nginx/conf.d/00-hyper-cs16-fastdl-ip.conf"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-fastdl-selfheal-v5-${STAMP}"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing controller: $SRC_CTL"; exit 2; }
[[ -d "$CSTRIKE" ]] || { echo "[ERROR] missing server cstrike: $CSTRIKE"; exit 2; }

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$CSTRIKE/server.cfg" ]] && cp -a "$CSTRIKE/server.cfg" "$BACKUP/server.cfg"
for f in fastdl.cfg server_download_fix.cfg SAFE_DOWNLOAD_MODE.cfg ENABLE_FASTDL_AFTER_VERIFY.cfg; do
  [[ -f "$CSTRIKE/$f" ]] && cp -a "$CSTRIKE/$f" "$BACKUP/$f"
done
[[ -f "$NGINX_CONF" ]] && cp -a "$NGINX_CONF" "$BACKUP/nginx-fastdl.conf"

echo "================================================================"
echo " HYPER-HOST CS 1.6 FASTDL SELF-HEAL v5"
echo " Server: #$SID"
echo " Public: $PUBLIC_IP"
echo " Backup: $BACKUP"
echo "================================================================"

echo "[1/8] Diagnose current server.cfg..."
python3 - "$CSTRIKE/server.cfg" <<'PY'
from pathlib import Path
import sys,re
p=Path(sys.argv[1])
raw=p.read_bytes()
print("server.cfg bytes:",len(raw))
print("real LF bytes:",raw.count(b'\n'))
print("literal \\n sequences:",raw.count(b'\\n'))
txt=raw.decode('utf-8','ignore')
logical=txt.replace('\\r\\n','\n').replace('\\n','\n').replace('\\r','\n')
print("FastDL BEGIN blocks:",len(re.findall(r'(?im)^\s*// HYPER-HOST FASTDL BEGIN',logical)))
print("sv_downloadurl entries:",len(re.findall(r'(?im)^\s*sv_downloadurl\b',logical)))
if raw.count(b'\n')==0 and raw.count(b'\\n')>20:
    print("[BAD] server.cfg is one physical line with escaped newlines")
PY

echo "[2/8] Patch panel FastDL logic..."
PATCHER="$(mktemp)"
echo '' | base64 -d > "$PATCHER"
python3 "$PATCHER" "$SRC_CTL"
python3 -m py_compile "$SRC_CTL"
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
rm -f "$PATCHER"

echo "[3/8] Install plain-HTTP IP FastDL nginx route..."
cat >"$NGINX_CONF" <<'EOF'
server {
    listen 80;
    listen [::]:80;
    server_name 90.189.208.25;

    access_log /var/log/nginx/hyper-cs16-fastdl-access.log;
    error_log  /var/log/nginx/hyper-cs16-fastdl-error.log warn;

    location ^~ /fastdl/ {
        alias /srv/hyper-cs16/fastdl/;
        autoindex off;
        default_type application/octet-stream;
        add_header Cache-Control "public, max-age=86400" always;
        add_header X-Hyper-FastDL "1" always;
    }

    location / {
        return 404;
    }
}
EOF
nginx -t
systemctl reload nginx

echo "[4/8] Firewall..."
if command -v ufw >/dev/null 2>&1; then
  ufw allow 80/tcp >/dev/null 2>&1 || true
fi

echo "[5/8] Clean sync + cfg repair + resource-case repair..."
"$LIVE_CTL" fastdl-sync "$SID"

echo "[6/8] Restart game server so repaired server.cfg is loaded..."
systemctl restart "hyper-cs16@${SID}.service"
sleep 3

echo "[7/8] Verify FastDL filesystem + HTTP..."
"$LIVE_CTL" fastdl-status "$SID" || true

PROBE="$(find "$FASTDL/maps" -maxdepth 1 -type f -iname 'zm_*.bsp' -print -quit 2>/dev/null || true)"
if [[ -z "$PROBE" ]]; then
  PROBE="$(find "$FASTDL" -type f -print -quit 2>/dev/null || true)"
fi
if [[ -n "$PROBE" ]]; then
  REL="${PROBE#"$FASTDL/"}"
  echo "Probe file: $REL"
  CODE="$(curl -sS --connect-timeout 3 --max-time 10 -H "Host: $PUBLIC_IP" -o /tmp/hh-fastdl-probe.bin -w '%{http_code}' "http://127.0.0.1/fastdl/$SID/$REL" || true)"
  echo "Local nginx HTTP code: $CODE"
  if [[ "$CODE" != "200" ]]; then
    echo "[ERROR] Local FastDL HTTP is not 200"
    exit 10
  fi
  echo "HTTP bytes: $(wc -c </tmp/hh-fastdl-probe.bin)"
  rm -f /tmp/hh-fastdl-probe.bin

  PUBLIC_CODE="$(curl -sS --connect-timeout 3 --max-time 10 -o /dev/null -w '%{http_code}' "http://$PUBLIC_IP/fastdl/$SID/$REL" || true)"
  echo "Public-IP HTTP code from this host: $PUBLIC_CODE"
  if [[ "$PUBLIC_CODE" != "200" ]]; then
    echo "[WARN] Public-IP self-test is not 200; this may be NAT hairpin."
    echo "       External clients still require TCP 80 -> $LAN_IP:80 on the router."
  fi
fi

echo "[8/8] Verify runtime cvars + repaired cfg..."
"$LIVE_CTL" rcon "$SID" "sv_downloadurl" || true
"$LIVE_CTL" rcon "$SID" "sv_allowdownload" || true
"$LIVE_CTL" rcon "$SID" "sv_allow_dlfile" || true

python3 - "$CSTRIKE/server.cfg" <<'PY'
from pathlib import Path
import sys,re
p=Path(sys.argv[1])
raw=p.read_bytes()
txt=raw.decode('utf-8','ignore')
print("real LF bytes after repair:",raw.count(b'\n'))
print("literal \\n after repair:",raw.count(b'\\n'))
print("FastDL blocks after repair:",len(re.findall(r'(?im)^\s*// HYPER-HOST FASTDL BEGIN\s*$',txt)))
urls=re.findall(r'(?im)^\s*sv_downloadurl\s+"?([^"\r\n]+)',txt)
print("sv_downloadurl:",urls[-1] if urls else 'MISSING')
PY

echo
echo "================================================================"
echo " [SUCCESS] FASTDL SELF-HEAL v5 INSTALLED"
echo "================================================================"
echo "Expected URL: http://$PUBLIC_IP/fastdl/$SID/"
echo "Nginx route:  $NGINX_CONF"
echo "FastDL root:  $FASTDL"
echo "Backup:       $BACKUP"
